for d in range(1,6):
    p=f"{C}/questions-D{d}.json"; qs=json.load(open(p)); n=0
    for q in qs:
        if q["id"] in O:
            assert len(O[q["id"]])==len(q["o"]); q["o"]=[{"it":a,"en":b} for a,b in O[q["id"]]]; n+=1
        if q["id"] in F:
            for k,v in F[q["id"]].items():
                q[k]=[{"it":a,"en":b} for a,b in v] if k=="o" else v
            q["type"]="multi" if len(q["c"])>1 else "single"; n+=1
    json.dump(qs,open(p,"w"),ensure_ascii=False,indent=1); print(p.rsplit('/',1)[1], "modificate", n)
